function canServeAll(trips: number[][], capacity: number): boolean {
  let last = 0;
  for (const t of trips) last = Math.max(last, t[2]);
  for (let m = 0; m < last; m++) {
    let load = 0;
    for (const [riders, from, to] of trips) if (from <= m && m < to) load += riders;
    if (load > capacity) return false;
  }
  return true;
}

