function canServeAll(trips: number[][], capacity: number): boolean {
  const ev: [number, number][] = [];
  for (const [riders, from, to] of trips) { ev.push([from, riders]); ev.push([to, -riders]); }
  // negative change first at the same mark: people leave before others board
  ev.sort((x, y) => x[0] - y[0] || x[1] - y[1]);
  let load = 0;
  for (const [, d] of ev) {
    load += d;
    if (load > capacity) return false;
  }
  return true;
}

