  let last = 0;
  for (const t of trips) last = Math.max(last, t[2]);
  const delta = new Array(last + 1).fill(0);
  for (const [riders, from, to] of trips) { delta[from] += riders; delta[to] -= riders; }
  let load = 0;
  for (const d of delta) {
    load += d;
    if (load > capacity) return false;
  }
  return true;
}

